window.__ModuleLoader__.load({
  id: '@local/dsh-theme',
  factory () {
    // z-index:-1 paints above the transparent boot canvas and below the panels, because body owns the stacking context on macOS.
    const WALLPAPER_CSS = `body::before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;background:url("data:image/jpeg;base64,") center/cover no-repeat fixed;opacity:.96}`


const ACCENT_TOKENS = {
  "--dsw-alias-state-business-primary": { light: "#d6478a", dark: "#ec6ba3" },
  "--dsw-alias-link": { light: "#d6478a", dark: "#ec6ba3" },
  "--dsw-alias-brand-primary-new-colorprimary-new-color": { light: "#d6478a", dark: "#ec6ba3" },
  "--dsw-alias-button-info-fill": { light: "#d6478a", dark: "#ec6ba3" },
  "--dsw-alias-button-info-hover": { light: "#c2387a", dark: "#f58bb8" },
  "--dsw-alias-bg-document-selection": { light: "rgba(214,71,138,.24)", dark: "rgba(236,107,163,.30)" },
  "--dsw-alias-interactive-bg-hover-accent": { light: "rgba(214,71,138,.14)", dark: "rgba(236,107,163,.20)" },
  "--dsw-alias-bg-base": { light: "rgba(255,255,255,.72)", dark: "rgba(21,21,23,.72)" },
  "--dsw-alias-bg-layer-1": { light: "rgba(255,255,255,.78)", dark: "rgba(35,35,36,.78)" },
  "--dsw-alias-bg-layer-2": { light: "rgba(255,255,255,.78)", dark: "rgba(44,44,46,.78)" },
  "--dsw-alias-bg-layer-3": { light: "rgba(255,255,255,.78)", dark: "rgba(53,54,56,.78)" },
  "--dsw-alias-bg-module-platform": { light: "rgba(245,246,247,.78)", dark: "rgba(53,54,56,.78)" }
}
    return { inject: ["locale", "theme"], apply (ctx) {
        if (typeof document === "undefined") return
        const locale = (() => { try { return ctx.get("locale") } catch { return null } })()
        if (locale) {
          try { ctx.effect(() => locale.addLanguage({ id: "zh-x", label: "中文（极简）", fallback: "zh" })) } catch {}
          try { ctx.effect(() => locale.register("chat", "zh-x", { "chat.deepDiving": "", "chat.deepDivingFor": "{duration} ···" })) } catch {}
          try { ctx.effect(() => locale.addLanguage({ id: "en-x", label: "English (Minimal)", fallback: "en" })) } catch {}
          try { ctx.effect(() => locale.register("chat", "en-x", { "chat.deepDiving": "", "chat.deepDivingFor": "{duration} ···" })) } catch {}
        }
        const theme = (() => { try { return ctx.get("theme") } catch { return null } })()
        if (theme) {
          try { ctx.effect(() => theme.overrideTokens("dsh-theme", ACCENT_TOKENS)) } catch {}
        }
        const style = document.createElement("style")
        style.dataset.plugin = "@local/dsh-theme"
        style.textContent = WALLPAPER_CSS
        document.head.appendChild(style)
        return () => style.remove()
      },
    }
  },
})
